test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 9500 }), 9500);
  assert.equal(lineTotal({ qty: 5, unitPrice: 9500 }), 47500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }), 3700);
});

test('lineTotal with qty 0 returns 0', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 9500 }), 0);
});

test('invoiceTotals sums line totals', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, vatRate: 21 },
      { qty: 1, unitPrice: 120000, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const subtotal = 5 * 9500 + 1 * 120000; // 167500
  const vat = 9975 + 25200; // 21% of each = 35175
  assert.deepEqual(totals, {
    subtotal,
    discount: 0,
    vat,
    total: subtotal + vat,
  });
  assert.equal(totals.subtotal, 167500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 35175);
  assert.equal(totals.total, 202675);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 6000, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  const subtotal = 60000;
  const vat = 12600; // 21% of 60000
  assert.deepEqual(totals, { subtotal, discount: 0, vat, total: subtotal + vat });
});

test('invoiceTotals with multiple lines of different products', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 8500, vatRate: 21 },
      { qty: 2, unitPrice: 980, vatRate: 21 },
      { qty: 100, unitPrice: 37, vatRate: 9 },
    ],
  };

  const subtotal = 3 * 8500 + 2 * 980 + 100 * 37; // 31160
  // VAT per line: 21% of 25500 = 5355, 21% of 1960 = 411.6 rounds to 412, 9% of 3700 = 333
  const vat = 5355 + 412 + 333; // 6100
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal + vat);
});

test('invoiceTotals with empty lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 0, discount: 0, vat: 0, total: 0 });
});

test('invoiceTotals calculated from createInvoice result', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier: 5% discount, 21% VAT
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const subtotal = 5 * 9500 + 1 * 120000; // 167500
  const discount = 8375; // 5% of 167500
  // VAT calculated per line: 21% of (47500 - 2375) + 21% of (120000 - 6000) = 21% of 45125 + 21% of 114000
  // = 9476.25 + 23940 = 33416.25, rounds to 33416
  const vat = 33416; // 21% of amount after discount per line
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal - discount + vat);
});

test('addLine adds a new line to a draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier: 5% discount
    issueDate: '2025-01-15',
